"use client";

import { useMemo, useState } from "react";
import { QiArchive, QiDeleteTrash, QiCircleDownload, QiPencil, QiCopy, QiMoreVert, QiSearch, QiUser } from "@/components/qiguan/icons";
import { Focusable } from "react-aria-components";
import {
  flexRender,
  getCoreRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table";
import type { ColumnDef, PaginationState, SortingState } from "@tanstack/react-table";
import { Avatar } from "@/components/base/avatar/avatar";
import { Chip } from "@/components/base/badges/chip";
import { StatusDot } from "@/components/base/badges/status-dot";
import { IconButton } from "@/components/base/buttons/icon-button";
import { Checkbox } from "@/components/base/checkbox/checkbox";
import {
  Dropdown,
  DropdownGroup,
  DropdownItem,
  DropdownPopover,
  DropdownTrigger,
} from "@/components/base/dropdown/dropdown";
import { InputBase } from "@/components/base/input/input";
import { Pagination } from "@/components/base/pagination/pagination";
import {
  SegmentedControl,
  SegmentedControlItem,
} from "@/components/base/segmented-control/segmented-control";
import { Select, SelectItem } from "@/components/base/select/select";
import type { SelectSize } from "@/components/base/select/select";
import {
  SEARCH_PILL_SURFACE,
  unsetTriggerClass,
} from "@/components/application/filters/filter-appearance";
import {
  Table,
  TableBody,
  TableCell,
  TableColumn,
  TableHeader,
  TableRow,
} from "@/components/base/table/table";
import type { TableSize } from "@/components/base/table/table";
import { Tooltip, TooltipTrigger } from "@/components/base/tooltip/tooltip";
import { ChevronSortDown } from "@/components/foundations/icons/chevrons";
import { cx } from "@/lib/cx";
import { formatThousands } from "@/lib/format-number";

/**
 * Advanced Data Table - the react-aria `Table` primitive rendered from a
 * @tanstack/react-table instance, styled to match the dashboard template's
 * customers table (node 3731:3201). TanStack owns sorting / pagination / row
 * selection; the price/product/region/search filters pre-filter the rows.
 */

type StatusColor = "lime" | "yellow" | "rose" | "cyan";
type Status = { label: string; color: StatusColor };

const STATUSES: Status[] = [
  { label: "已发货", color: "lime" },
  { label: "待收货", color: "yellow" },
  { label: "配送失败", color: "rose" },
  { label: "已确认", color: "cyan" },
];

const PRODUCTS = ["运动鞋", "背包", "智能手表", "耳机", "太阳镜", "钱包"];
const REGIONS = ["北美", "欧洲", "亚洲", "大洋洲"];
const MONTHS = ["1月", "2月", "3月", "4月", "5月", "6月", "7月", "8月", "9月", "10月", "11月", "12月"];

const PRICE_BUCKETS: { id: string; label: string; test: (p: number) => boolean }[] = [
  { id: "all", label: "全部价格", test: () => true },
  { id: "under-100", label: "¥100 以下", test: (p) => p < 100 },
  { id: "100-500", label: "¥100 – ¥500", test: (p) => p >= 100 && p <= 500 },
  { id: "500-1000", label: "¥500 – ¥1,000", test: (p) => p > 500 && p <= 1000 },
  { id: "over-1000", label: "¥1,000 以上", test: (p) => p > 1000 },
];

type Customer = {
  id: string;
  name: string;
  purchase: "completed" | "waiting" | "processing";
  status: Status;
  product: string;
  region: string;
  price: number;
  updated: string;
  updatedTs: number;
};

/**
 * 头像底色。此前前 8 行挂的是上游模板的真实人物照片（/avatars/*.webp），
 * 而且与中文姓名根本对不上（「张伟」配了一张外籍面孔）。现在全部改为
 * 按姓名生成的纯底色头像，不再使用任何照片。
 *
 * 只取 Avatar 组件已有的四种色调：它们是设计系统里唯一成对定义了背景色与
 * 文字色的组合，能保证对比度。要更多颜色得同时补文字色，不在本次改动范围。
 */
const AVATAR_COLORS = ["neutral", "blue", "lime", "pink"] as const;
type AvatarColorKey = (typeof AVATAR_COLORS)[number];

/** 姓名 → 底色。同名恒定同色（不是随机），换名字才可能换色。 */
function avatarColorOf(name: string): AvatarColorKey {
  let hash = 0;
  for (const ch of name) hash = (hash * 31 + (ch.codePointAt(0) ?? 0)) % 100000;
  return AVATAR_COLORS[hash % AVATAR_COLORS.length];
}

const SURNAMES = ["张", "王", "李", "赵", "刘", "陈", "杨", "黄", "周", "吴", "徐", "孙", "马", "朱", "胡", "林", "郭", "何", "高", "罗"];
const GIVEN = ["伟", "芳", "娜", "秀英", "敏", "静", "丽", "强", "磊", "洋", "艳", "勇", "军", "杰", "娟", "涛", "明", "超", "霞", "燕"];

function makeRng(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function formatPrice(n: number) {
  return n >= 1000 ? `¥${Math.floor(n / 1000)}.${String(n % 1000).padStart(3, "0")}` : `¥${n}`;
}

/** 头像显示姓名后两字：两字姓名即全名（张伟），三字及以上取后两字（欧阳明 → 阳明）。 */
function initialsOf(name: string) {
  return name.slice(-2);
}

const CUSTOMERS: Customer[] = (() => {
  const rng = makeRng(42);
  const pick = <T,>(arr: T[]) => arr[Math.floor(rng() * arr.length)];
  return Array.from({ length: 48 }, (_, i) => {
    const status = pick(STATUSES);
    const purchase: Customer["purchase"] =
      rng() < 0.24
        ? "processing"
        : status.label === "已发货" || status.label === "已确认"
          ? "completed"
          : "waiting";
    const price = 20 + Math.floor(rng() * 3980);
    const monthIdx = Math.floor(rng() * 12);
    const day = 1 + Math.floor(rng() * 28);
    const updated = `2026年${MONTHS[monthIdx]}${String(day).padStart(2, "0")}日`;
    const updatedTs = new Date(2026, monthIdx, day).getTime();
    const base = {
      id: String(i),
      purchase,
      status,
      product: pick(PRODUCTS),
      region: pick(REGIONS),
      price,
      updated,
      updatedTs,
    };
    const name = `${pick(SURNAMES)}${pick(GIVEN)}`;
    return { ...base, name };
  });
})();

const PER_PAGE = 8;

function PurchaseSelect({
  value,
  name,
  size = "md",
}: {
  value: Customer["purchase"];
  name: string;
  size?: SelectSize;
}) {
  return (
    <Select
      aria-label={`${name} 的采购状态`}
      defaultSelectedKey={value}
      size={size}
      className={size === "sm" ? "w-[132px]" : "w-[142px]"}
    >
      <SelectItem id="completed" textValue="已完成">
        <StatusDot color="green" />
        已完成
      </SelectItem>
      <SelectItem id="waiting" textValue="等待中">
        <StatusDot color="yellow" />
        等待中
      </SelectItem>
      <SelectItem id="processing" textValue="处理中">
        <StatusDot color="indigo" />
        处理中
      </SelectItem>
    </Select>
  );
}

function SortChevron({ dir }: { dir: false | "asc" | "desc" }) {
  return (
    <ChevronSortDown
      className={cx(
        "size-6 shrink-0 transition-[transform,color] duration-150",
        dir === "asc" && "rotate-180",
        dir ? "text-text-secondary" : "text-text-tertiary",
      )}
    />
  );
}

/** Icon-only row action with a tooltip label - `IconButton` (a plain
 *  `<button>`) is wrapped in `Focusable` so react-aria's `TooltipTrigger`
 *  can attach hover/focus behavior. */
function RowActionButton({
  icon,
  label,
}: {
  icon: typeof QiPencil;
  label: string;
}) {
  return (
    <TooltipTrigger delay={200}>
      <Focusable>
        <IconButton icon={icon} size="small" aria-label={label} />
      </Focusable>
      <Tooltip size="md">{label}</Tooltip>
    </TooltipTrigger>
  );
}

const MORE_MENU_ACTIONS = [
  { icon: QiUser, label: "查看资料" },
  { icon: QiCopy, label: "复制行" },
  { icon: QiCircleDownload, label: "下载发票" },
  { icon: QiArchive, label: "归档客户" },
] as const;

/** The "⋮" action: tooltip on hover, contextual dropdown menu on click. The
 *  trigger is styled to match `IconButton`'s small secondary recipe (nesting
 *  the real IconButton inside DropdownTrigger would nest <button>s). */
function RowMoreMenu({ name }: { name: string }) {
  const [isOpen, setIsOpen] = useState(false);
  return (
    <Dropdown isOpen={isOpen} onOpenChange={setIsOpen}>
      <TooltipTrigger delay={200}>
        <DropdownTrigger
          aria-label={`${name} 的更多操作`}
          className={cx(
            "relative inline-flex size-8 shrink-0 items-center justify-center rounded-2lg",
            "border border-border-button-default bg-background-primary-default text-foreground-icon-primary shadow-xs",
            "transition-[background-color,border-color,box-shadow,color] duration-150 ease",
            "hover:border-border-button-hover hover:bg-background-primary-hover",
            isOpen && "border-border-button-active bg-background-primary-active",
          )}
        >
          <QiMoreVert className="size-4 shrink-0" aria-hidden />
        </DropdownTrigger>
        <Tooltip size="md">更多操作</Tooltip>
      </TooltipTrigger>
      <DropdownPopover aria-label={`${name} 的更多操作`} placement="bottom end" className="w-[220px] p-2">
        <DropdownGroup>
          {MORE_MENU_ACTIONS.map(({ icon: Icon, label }) => (
            <DropdownItem key={label} onSelect={() => setIsOpen(false)} className="px-2 py-1.5">
              <Icon className="size-[18px] shrink-0 text-foreground-icon-secondary" aria-hidden />
              <span className="truncate text-body-medium whitespace-nowrap text-text-primary">{label}</span>
            </DropdownItem>
          ))}
        </DropdownGroup>
      </DropdownPopover>
    </Dropdown>
  );
}

export function DataTableExample({
  showSizeToggle = true,
  pageSize = PER_PAGE,
}: {
  /** Show the Normal / Compact density control below the table. */
  showSizeToggle?: boolean;
  /** Rows per page - the landing collage shows the 5-row crop from Figma. */
  pageSize?: number;
} = {}) {
  const [sorting, setSorting] = useState<SortingState>([]);
  const [rowSelection, setRowSelection] = useState<Record<string, boolean>>({ "1": true, "2": true });
  const [pagination, setPagination] = useState<PaginationState>({ pageIndex: 0, pageSize });
  const [priceFilter, setPriceFilter] = useState("all");
  const [productFilter, setProductFilter] = useState("all");
  const [regionFilter, setRegionFilter] = useState("all");
  const [query, setQuery] = useState("");
  const [size, setSize] = useState<TableSize>("md");
  const avatarSize = size === "sm" ? "xs" : "sm";

  const data = useMemo(() => {
    const bucket = PRICE_BUCKETS.find((b) => b.id === priceFilter) ?? PRICE_BUCKETS[0];
    const q = query.trim().toLowerCase();
    return CUSTOMERS.filter(
      (c) =>
        bucket.test(c.price) &&
        (productFilter === "all" || c.product === productFilter) &&
        (regionFilter === "all" || c.region === regionFilter) &&
        (q === "" || c.name.toLowerCase().includes(q)),
    );
  }, [priceFilter, productFilter, regionFilter, query]);

  const columns = useMemo<ColumnDef<Customer>[]>(
    () => [
      {
        accessorKey: "name",
        header: "客户名称",
        cell: ({ row }) => {
          const c = row.original;
          return (
            <div className="flex min-w-0 items-center gap-2">
              <Checkbox
                slot={null}
                aria-label={`选择 ${c.name}`}
                isSelected={row.getIsSelected()}
                onChange={(v) => row.toggleSelected(!!v)}
              />
              <Avatar
                size={avatarSize}
                color={avatarColorOf(c.name)}
                initials={initialsOf(c.name)}
                className={cx(
                  "leading-none font-semibold tracking-[-0.02em]",
                  // 两个中文字塞进 24px/20px 的圆形里必须压字号，
                  // 否则会被 Avatar 的 overflow-hidden 裁掉一半。
                  avatarSize === "xs" ? "text-[9px]" : "text-[10px]",
                )}
              />
              <span className="truncate text-body-medium text-text-primary">{c.name}</span>
            </div>
          );
        },
      },
      {
        id: "purchase",
        enableSorting: false,
        header: "采购状态",
        cell: ({ row }) => (
          <PurchaseSelect value={row.original.purchase} name={row.original.name} size={size} />
        ),
      },
      {
        id: "status",
        enableSorting: false,
        header: "状态",
        cell: ({ row }) => (
          <Chip variant={size === "sm" ? "caption" : "bold"} color={row.original.status.color}>
            {row.original.status.label}
          </Chip>
        ),
      },
      {
        accessorKey: "updatedTs",
        header: "更新时间",
        cell: ({ row }) => (
          <span className="whitespace-nowrap text-body-medium text-text-primary">{row.original.updated}</span>
        ),
      },
      {
        accessorKey: "price",
        header: "价格",
        cell: ({ row }) => (
          <Chip variant={size === "sm" ? "caption" : "subtle"} color="gray">
            {formatPrice(row.original.price)}
          </Chip>
        ),
      },
      {
        id: "actions",
        enableSorting: false,
        header: "操作",
        cell: ({ row }) => (
          <div className="flex items-center justify-end gap-2.5">
            <RowActionButton icon={QiDeleteTrash} label="删除" />
            <RowActionButton icon={QiPencil} label="编辑" />
            <RowMoreMenu name={row.original.name} />
          </div>
        ),
      },
    ],
    [avatarSize, size],
  );

  const table = useReactTable({
    data,
    columns,
    getRowId: (row) => row.id,
    state: { sorting, rowSelection, pagination },
    onSortingChange: setSorting,
    onRowSelectionChange: setRowSelection,
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    enableRowSelection: true,
  });

  const resetPage = () => table.setPageIndex(0);
  const headers = table.getHeaderGroups()[0].headers;
  const rows = table.getRowModel().rows;
  const totalPages = table.getPageCount();
  const colWidths: Record<string, string> = {
    name: "w-[240px]",
    purchase: "w-[172px]",
    status: "w-[168px]",
    updatedTs: "w-[160px]",
    price: "w-[140px]",
    actions: "w-[132px]",
  };

  return (
    <section
      className={cx(
        "flex w-full flex-col rounded-2xl border border-border-table pt-2",
        totalPages > 1 ? "pb-3" : "pb-0",
      )}
    >
      {/* Toolbar */}
      <div className="flex w-full flex-col items-start gap-3 px-3 py-1 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-col justify-center">
          <p className="text-body-medium whitespace-nowrap text-text-tertiary">结果总数</p>
          <p className="text-body-medium whitespace-nowrap text-text-primary">
            {formatThousands(data.length)} 个客户
          </p>
        </div>
        <div className="-mx-3 flex w-[calc(100%+1.5rem)] items-center gap-2.5 overflow-x-auto px-3 sm:mx-0 sm:w-auto sm:flex-wrap sm:justify-end sm:overflow-visible sm:px-0">
          <Select
            aria-label="按价格筛选"
            className="shrink-0"
            popoverClassName="min-w-40"
            selectedKey={priceFilter}
            onSelectionChange={(k) => {
              setPriceFilter(String(k));
              resetPage();
            }}
            triggerClassName={unsetTriggerClass(priceFilter)}
          >
            {PRICE_BUCKETS.map((b) => (
              <SelectItem key={b.id} id={b.id} textValue={b.label}>
                {b.label}
              </SelectItem>
            ))}
          </Select>
          <Select
            aria-label="按产品筛选"
            className="shrink-0"
            popoverClassName="min-w-40"
            selectedKey={productFilter}
            onSelectionChange={(k) => {
              setProductFilter(String(k));
              resetPage();
            }}
            triggerClassName={unsetTriggerClass(productFilter)}
          >
            <SelectItem id="all" textValue="全部产品">
              全部产品
            </SelectItem>
            {PRODUCTS.map((p) => (
              <SelectItem key={p} id={p} textValue={p}>
                {p}
              </SelectItem>
            ))}
          </Select>
          <Select
            aria-label="按地区筛选"
            className="shrink-0"
            popoverClassName="min-w-40"
            selectedKey={regionFilter}
            onSelectionChange={(k) => {
              setRegionFilter(String(k));
              resetPage();
            }}
            triggerClassName={unsetTriggerClass(regionFilter)}
          >
            <SelectItem id="all" textValue="全部地区">
              全部地区
            </SelectItem>
            {REGIONS.map((r) => (
              <SelectItem key={r} id={r} textValue={r}>
                {r}
              </SelectItem>
            ))}
          </Select>
          <InputBase
            aria-label="搜索客户"
            placeholder="搜索"
            leadingIcon={QiSearch}
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              resetPage();
            }}
            fieldClassName={cx(
              SEARCH_PILL_SURFACE,
              "min-w-[153px] flex-1 sm:w-[153px] sm:min-w-0 sm:flex-none",
            )}
          />
            {showSizeToggle && (
              // 与 `RecordTable` 一致：密度是列表的视图选项，放工具条里才不用
              // 先滚完整个列表才够得着（旧位置在卡片外面、页面最底部）。
              <SegmentedControl
                aria-label="表格密度"
                className="shrink-0"
                selectedKeys={new Set([size])}
                onSelectionChange={(keys) => {
                  const next = [...keys][0];
                  if (next) setSize(next as TableSize);
                }}
              >
                <SegmentedControlItem id="md">标准</SegmentedControlItem>
                <SegmentedControlItem id="sm">紧凑</SegmentedControlItem>
              </SegmentedControl>
            )}
        </div>
      </div>

      {/* Table */}
      <div className="mt-2">
        <Table aria-label="客户" size={size} selectionMode="none" className="min-w-[1000px]">
          <TableHeader>
            {headers.map((header) => {
              const id = header.column.id;
              const canSort = header.column.getCanSort();
              const label = flexRender(header.column.columnDef.header, header.getContext());
              return (
                <TableColumn key={header.id} id={header.id} isRowHeader={id === "name"} className={colWidths[id]}>
                  {id === "name" ? (
                    <div className="flex items-center gap-2">
                      <Checkbox
                        slot={null}
                        aria-label="选择本页全部客户"
                        isSelected={table.getIsAllPageRowsSelected()}
                        isIndeterminate={table.getIsSomePageRowsSelected() && !table.getIsAllPageRowsSelected()}
                        onChange={(v) => table.toggleAllPageRowsSelected(!!v)}
                      />
                      <button
                        type="button"
                        onClick={header.column.getToggleSortingHandler()}
                        className="flex cursor-pointer items-center gap-0.5"
                      >
                        {label}
                        <SortChevron dir={header.column.getIsSorted()} />
                      </button>
                    </div>
                  ) : canSort ? (
                    <button
                      type="button"
                      onClick={header.column.getToggleSortingHandler()}
                      className="flex cursor-pointer items-center gap-0.5"
                    >
                      {label}
                      <SortChevron dir={header.column.getIsSorted()} />
                    </button>
                  ) : (
                    label
                  )}
                </TableColumn>
              );
            })}
          </TableHeader>
          <TableBody
            renderEmptyState={() => (
              <div className="flex h-40 items-center justify-center text-body-medium text-text-tertiary">
                没有符合筛选条件的客户。
              </div>
            )}
          >
            {rows.map((row) => {
              const selected = row.getIsSelected();
              return (
                <TableRow
                  key={row.id}
                  id={row.id}
                  style={
                    selected
                      ? { backgroundColor: "var(--color-background-secondary-default)" }
                      : undefined
                  }
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id} className={colWidths[cell.column.id]}>
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
      </div>

      {/* Pagination footer */}
      {totalPages > 1 && (
        <div className="border-t border-separator-border px-3 pt-3">
          <Pagination
            page={pagination.pageIndex + 1}
            totalPages={totalPages}
            onChange={(p) => table.setPageIndex(p - 1)}
          />
        </div>
      )}
    </section>
  );
}
